<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/fiscal_result_service.php';require_once __DIR__.'/report_error.php';
try{$uid=(int)requireAuth()->id;$year=(int)($_GET['year']??date('Y'));if($year<2000||$year>2200)throw new InvalidArgumentException('Invalid year');$conn=db();requirePermission($conn,$uid,'reports.view');$current=operationalAccountingResult($conn,$uid,$year);$s=$conn->prepare("SELECT r.*,ROUND(COALESCE(SUM(CASE WHEN a.adjustment_type='ADDITION' THEN a.amount ELSE 0 END),0),3) additions,ROUND(COALESCE(SUM(CASE WHEN a.adjustment_type='DEDUCTION' THEN a.amount ELSE 0 END),0),3) deductions FROM erp_fiscal_reconciliations r LEFT JOIN erp_fiscal_adjustments a ON a.reconciliation_id=r.id WHERE r.user_id=? AND r.fiscal_year=? GROUP BY r.id");$s->bind_param('ii',$uid,$year);$s->execute();$header=$s->get_result()->fetch_assoc();$s->close();$adjustments=[];if($header){$s=$conn->prepare('SELECT id,adjustment_type,timing,category,description,amount,legal_basis,notes,created_at FROM erp_fiscal_adjustments WHERE reconciliation_id=? AND user_id=? ORDER BY adjustment_type,category,id');$s->bind_param('ii',$header['id'],$uid);$s->execute();$adjustments=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$accounting=(float)($header['accounting_result']??$current['result']);$add=(float)($header['additions']??0);$ded=(float)($header['deductions']??0);jsonResponse(['success'=>true,'year'=>$year,'header'=>$header?:null,'current_operational_result'=>$current,'snapshot_difference'=>round($current['result']-$accounting,3),'additions'=>$add,'deductions'=>$ded,'taxable_result'=>round($accounting+$add-$ded,3),'adjustments'=>$adjustments,'filing_ready'=>false]);}catch(Throwable $e){reportFailureResponse($e,'Could not load the fiscal reconciliation.','FISCAL_RECONCILIATION_LOAD_FAILED');}
